#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/control/shared_capabilities/shared_capabilities.hpp"
#include "gui_forms/image_list.hpp"
#include "gui_forms/types.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// TreeView's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/tree_view.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// The selected item's stable ID, or empty; a view, since replacing the items keeps or clears it. A change makes the item active and raises selection_changed; an ID not in the model throws std::out_of_range.
template <typename Declaring>
struct TreeViewSelectedIdCapability {
    PropertyView<std::string, TreeViewSelectedIdCapability<Declaring>> selected_id;

    static void assign(TreeViewSelectedIdCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.selected_id), std::move(incoming));
    }

    static std::string read(const TreeViewSelectedIdCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::string current = control.read_view(capability.selected_id);
        return current;
    }
};

// The row height in logical units, 14 to 256 (std::invalid_argument otherwise).
template <typename Declaring>
struct TreeViewItemHeightCapability {
    PropertyCell<double, TreeViewItemHeightCapability<Declaring>> item_height{24.0};

    static void assign(TreeViewItemHeightCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.item_height), incoming);
        if (!capability.item_height.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.item_height));
    }
};

// The width of one tree level in logical units, 8 to 96 (std::invalid_argument otherwise).
template <typename Declaring>
struct TreeViewIndentationCapability {
    PropertyCell<double, TreeViewIndentationCapability<Declaring>> indentation{18.0};

    static void assign(TreeViewIndentationCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.indentation), incoming);
        if (!capability.indentation.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.indentation));
    }
};

// Whether expandable items draw their expander glyph.
template <typename Declaring>
struct TreeViewShowExpandersCapability {
    PropertyCell<bool, TreeViewShowExpandersCapability<Declaring>> show_expanders{true};

    static void assign(TreeViewShowExpandersCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.show_expanders), incoming);
        if (!capability.show_expanders.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.show_expanders));
    }
};

// The images that the items' image keys name; a list must be alive and belong to this view's Window (std::invalid_argument otherwise). A change follows the new list's changes.
template <typename Declaring>
struct TreeViewImageListCapability {
    PropertyCell<std::shared_ptr<ImageList>, TreeViewImageListCapability<Declaring>> image_list{};

    static void assign(TreeViewImageListCapability& capability, std::shared_ptr<ImageList> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.image_list), incoming);
        if (!capability.image_list.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.image_list));
    }
};

// Every TreeView capability, in the order the declaring class takes them.
template <typename Declaring>
struct TreeViewCapabilities : public TreeViewSelectedIdCapability<Declaring>,
                              public TreeViewItemHeightCapability<Declaring>,
                              public TreeViewIndentationCapability<Declaring>,
                              public TreeViewShowExpandersCapability<Declaring>,
                              public FontCapability<Declaring>,
                              public TreeViewImageListCapability<Declaring> {
    TreeViewCapabilities() : FontCapability<Declaring>(FontSpec{FontRole::content, 12.0, 400, false}) {}
};

} // namespace gui_forms
